def lda(Xtr,ytr,Xva, shrink=1e-2):
    X0=Xtr[ytr==0]; X1=Xtr[ytr==1]
    m0=X0.mean(0); m1=X1.mean(0)
    S0=np.cov(X0, rowvar=False, bias=True); S1=np.cov(X1, rowvar=False, bias=True)
    S=((len(X0)*S0 + len(X1)*S1) / len(Xtr)); S.flat[::S.shape[0]+1] += shrink
    w=np.linalg.solve(S, m1-m0); b=-0.5*(m1+m0)@w + np.log((ytr==1).mean() / (ytr==0).mean())
    return ((Xva@w + b) > 0).astype(int)

def gnb(Xtr,ytr,Xva, var_smooth=1e-2):
    priors=[(ytr==c).mean() for c in [0,1]]; mus=[]; vars=[]
    for c in [0,1]:
